import{_ as a,o as t,a as s,a2 as i}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"Cache Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/cache-strategy.md","filePath":"advanced/cache-strategy.md","lastUpdated":1789319767000}'),n={name:"advanced/cache-strategy.md"};function o(c,e,d,r,h,l){return t(),s("div",null,e[0]||(e[0]=[i(`<h1 id="cache-strategy" tabindex="-1">Cache Strategy <a class="header-anchor" href="#cache-strategy" aria-label="Permalink to &quot;Cache Strategy&quot;">​</a></h1><p>Bagisto implements a multi-layered caching strategy to optimize performance across the storefront, admin panel, and data access layers. Understanding these layers helps you build performant custom packages and debug cache-related issues.</p><h2 id="cache-layers-overview" tabindex="-1">Cache Layers Overview <a class="header-anchor" href="#cache-layers-overview" aria-label="Permalink to &quot;Cache Layers Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th><th>Scope</th><th>Configuration</th></tr></thead><tbody><tr><td><strong>Application Cache</strong></td><td>Database / File / Redis / Memcached</td><td>Key-value storage for config, routes, repository results</td><td><code>CACHE_STORE</code> in <code>.env</code></td></tr><tr><td><strong>Repository Cache</strong></td><td>Prettus L5 Repository on top of the application cache</td><td>Automatic model query caching</td><td><code>config/repository.php</code></td></tr><tr><td><strong>Full Page Cache (FPC)</strong></td><td>Spatie ResponseCache</td><td>Caches entire HTTP responses</td><td><strong>Configuration → Cache Management</strong> and <code>config/responsecache.php</code></td></tr><tr><td><strong>Image Cache</strong></td><td>HTTP caching only</td><td>Resized images</td><td><code>config/imagecache.php</code></td></tr><tr><td><strong>Search Index</strong></td><td>Elasticsearch</td><td>Product search index</td><td><strong>Configuration → Search Engines</strong></td></tr><tr><td><strong>Session Store</strong></td><td>Database / Redis</td><td>User session data</td><td><code>SESSION_DRIVER</code> in <code>.env</code></td></tr></tbody></table><h2 id="application-cache" tabindex="-1">Application Cache <a class="header-anchor" href="#application-cache" aria-label="Permalink to &quot;Application Cache&quot;">​</a></h2><p>Configured via the <code>CACHE_STORE</code> environment variable. The shipped <code>.env.example</code> uses the <code>database</code> store on the current development version (<code>file</code> on Bagisto 2.4); the <code>cache</code> table is created by a root migration.</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .env</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CACHE_STORE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=database</span></span></code></pre></div><p>For production, Redis is recommended:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CACHE_STORE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=redis</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">REDIS_HOST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">REDIS_PORT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=6379</span></span></code></pre></div><p><code>config/cache.php</code> sets <code>serializable_classes</code> to <code>true</code> on purpose: the repository cache stores Eloquent models and collections, which Laravel 13&#39;s default of <code>false</code> would return as incomplete objects.</p><p>Clear the application cache:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache:clear</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or clear everything at once</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimize:clear</span></span></code></pre></div><h2 id="repository-cache" tabindex="-1">Repository Cache <a class="header-anchor" href="#repository-cache" aria-label="Permalink to &quot;Repository Cache&quot;">​</a></h2><p>Bagisto uses the <a href="https://github.com/prettus/l5-repository" target="_blank" rel="noreferrer">Prettus L5 Repository</a> package, and <code>Webkul\\Core\\Eloquent\\Repository</code> implements its <code>CacheableInterface</code>. Caching is off by default: <code>config/repository.php</code> ships <code>&#39;enabled&#39; =&gt; false</code>, and even when enabled only the repositories listed under <code>cache.repositories</code> in that file take part. For those, <code>all()</code>, <code>paginate()</code> and the finders cache their results; <code>find()</code> and <code>findOrFail()</code> are redefined without caching and always query the database.</p><h3 id="automatic-invalidation" tabindex="-1">Automatic Invalidation <a class="header-anchor" href="#automatic-invalidation" aria-label="Permalink to &quot;Automatic Invalidation&quot;">​</a></h3><p>Each cache key carries a generation token, and every <code>create()</code>, <code>update()</code> and <code>delete()</code> through a cached repository advances it. The <code>Webkul\\Core\\Listeners\\CleanCacheRepository</code> listener, registered in <code>Webkul\\Core\\Providers\\EventServiceProvider</code>, does the same on Prettus&#39; <code>RepositoryEntityCreated</code>, <code>RepositoryEntityUpdated</code> and <code>RepositoryEntityDeleted</code> events.</p><div class="tip custom-block"><p class="custom-block-title">Opt in deliberately</p><p>A repository in your own package is not cached unless you enable the cache and add the class to <code>cache.repositories</code>. Once you do, write through the repository: a table changed with Eloquent or the query builder directly serves stale reads until the token moves for another reason.</p></div><h2 id="full-page-cache-fpc" tabindex="-1">Full Page Cache (FPC) <a class="header-anchor" href="#full-page-cache-fpc" aria-label="Permalink to &quot;Full Page Cache (FPC)&quot;">​</a></h2><p>The FPC package (<code>Webkul\\FPC</code>) uses <a href="https://github.com/spatie/laravel-responsecache" target="_blank" rel="noreferrer">Spatie ResponseCache</a> to cache complete HTTP responses for storefront pages.</p><h3 id="enabling-fpc" tabindex="-1">Enabling FPC <a class="header-anchor" href="#enabling-fpc" aria-label="Permalink to &quot;Enabling FPC&quot;">​</a></h3><p>The switch is in the admin: <strong>Configuration → Cache Management → Full Page Cache</strong> has an <strong>Enabled</strong> toggle (on by default), a <strong>Lifetime</strong> in minutes and a <strong>Flush</strong> button. <code>config/responsecache.php</code> hard-codes <code>&#39;enabled&#39; =&gt; true</code>; the <code>RESPONSE_CACHE_ENABLED</code> variable is not read. The environment keys that do apply are <code>RESPONSE_CACHE_DRIVER</code> (default <code>file</code>) and <code>RESPONSE_CACHE_LIFETIME</code> in seconds (default one week), which the admin lifetime overrides when set.</p><h3 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h3><p><code>Webkul\\FPC\\CacheProfiles\\FullPageCacheProfile</code> decides per request. A response is cached when the route carries the <code>cache.response</code> middleware, the admin toggle is on and no customer is signed in. The seven storefront routes that carry it are the home page, the product/category slug fallback, CMS pages, the contact page (and its POST), the search page and the compare page. The cache key includes the host, channel, locale and currency, and drops every query parameter except <code>query</code> on the search page and the tracking parameters listed in <code>ignored_query_parameters</code>.</p><p>Three replacers punch holes for content that must stay live inside a cached page: the CSRF token, flash messages and the mini cart.</p><h3 id="what-invalidates-the-cache" tabindex="-1">What Invalidates the Cache <a class="header-anchor" href="#what-invalidates-the-cache" aria-label="Permalink to &quot;What Invalidates the Cache&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>What Gets Invalidated</th></tr></thead><tbody><tr><td>Product create/update/delete</td><td>The product page, every category page it sits in, the home page, and the same for its parent bundle/grouped/configurable products</td></tr><tr><td>Category create/update/delete</td><td>Category page URL</td></tr><tr><td>Price reindex (<code>catalog.product.price.reindex.after</code>, <code>promotions.catalog_rule.reindex.after</code>)</td><td>The affected products, or the whole cache when every price was reindexed</td></tr><tr><td>Review update/delete</td><td>Corresponding product page</td></tr><tr><td>Order placed / cancelled, refund issued</td><td>Product pages of the items (stock changes)</td></tr><tr><td>CMS page update/delete</td><td>CMS page URL</td></tr><tr><td>URL rewrite update/delete</td><td>Old and new URLs</td></tr><tr><td>Section create/update/delete</td><td>The home page, or everything when the section type renders in the layout</td></tr><tr><td>Channel update</td><td>Full cache clear</td></tr><tr><td>Configuration save</td><td>Full cache clear</td></tr></tbody></table><p>Targeted flushes go through <code>Webkul\\FPC\\Concerns\\ForgetsPages</code>, which forgets every URL for every channel host, locale and currency combination, because each is a separate cache entry.</p><h3 id="fpc-event-listeners" tabindex="-1">FPC Event Listeners <a class="header-anchor" href="#fpc-event-listeners" aria-label="Permalink to &quot;FPC Event Listeners&quot;">​</a></h3><p>The listeners live in <code>packages/Webkul/FPC/src/Listeners/</code> and are registered in <code>Webkul\\FPC\\Providers\\EventServiceProvider</code>: <code>Product</code>, <code>Category</code>, <code>Price</code>, <code>Review</code>, <code>Order</code>, <code>Refund</code>, <code>Page</code>, <code>URLRewrite</code>, <code>Section</code>, <code>Channel</code> and <code>CoreConfig</code>.</p><div class="warning custom-block"><p class="custom-block-title">Admin Panel</p><p>The admin panel is explicitly excluded from response caching via the <code>NoCacheMiddleware</code> applied to all admin routes. This ensures admin users always see fresh data.</p></div><h2 id="image-cache" tabindex="-1">Image Cache <a class="header-anchor" href="#image-cache" aria-label="Permalink to &quot;Image Cache&quot;">​</a></h2><p>Resized images at <code>/cache/{template}/{path}</code> are not written to disk. The controller resizes on every request and relies on an <code>ETag</code> and a <code>Cache-Control: max-age</code> header of <code>imagecache.lifetime</code> minutes (30 days by default). There is nothing to clear; a changed template takes effect when a client revalidates. See <a href="./../theme-development/image-cache-templates.html">Image Cache Templates</a>.</p><h2 id="cache-in-custom-packages" tabindex="-1">Cache in Custom Packages <a class="header-anchor" href="#cache-in-custom-packages" aria-label="Permalink to &quot;Cache in Custom Packages&quot;">​</a></h2><p>When building custom packages that modify data visible on the storefront, make sure to invalidate FPC for affected URLs:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Spatie\\ResponseCache\\Facades\\ResponseCache</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Clear specific URLs</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ResponseCache</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forget</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/products/my-product&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Clear everything</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ResponseCache</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clear</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>For a package that renders inside a cached page, use <code>Webkul\\FPC\\FullPageCache::willCache()</code> in the view to decide whether to emit a replacer placeholder instead of live content.</p><p>For repository-level cache, writing through a cached repository ensures automatic invalidation.</p><h2 id="cache-configuration-for-production" tabindex="-1">Cache Configuration for Production <a class="header-anchor" href="#cache-configuration-for-production" aria-label="Permalink to &quot;Cache Configuration for Production&quot;">​</a></h2><p>Recommended <code>.env</code> settings for production:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CACHE_STORE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=redis</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SESSION_DRIVER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=redis</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">QUEUE_CONNECTION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=redis</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RESPONSE_CACHE_DRIVER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=redis</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">REDIS_HOST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">REDIS_PORT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=6379</span></span></code></pre></div><p>Run these commands after deployment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:cache</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route:cache</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view:cache</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> event:cache</span></span></code></pre></div><p>The buttons under <strong>Configuration → Cache Management</strong> run <code>config:cache</code>, <code>route:cache</code>, <code>view:cache</code> and <code>optimize</code> on the build side, and <code>config:clear</code>, <code>cache:clear</code>, <code>clear-compiled</code>, <code>event:clear</code>, <code>route:clear</code>, <code>view:clear</code> and <code>optimize:clear</code> on the clear side (<code>Webkul\\Admin\\Services\\CacheManagerService</code>); the full page cache has its own <strong>Flush</strong> button. To clear all caches at once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimize:clear</span></span></code></pre></div>`,44)]))}const k=a(n,[["render",o]]);export{g as __pageData,k as default};
